6	-----------------------------------------------------------------------------*/
7	
8	#include "mimalloc.h"
9	#include "mimalloc/internal.h"
10	#include "mimalloc/prim-tls.h"
11	
12	// pre-allocate the main subprocess structure.
13	static mi_decl_cache_align mi_subproc_t mi_process_subproc_main = mi_init_struct_zero;
14	static mi_subproc_t* mi_subprocs = NULL;
15	static mi_lock_t     mi_subprocs_lock = MI_LOCK_INITIALIZER;
16	
17	
18	/* -----------------------------------------------------------
19	  Meta-data allocation
20	  We allocate thread local data and theaps through a dedicated
21	  theap `subproc.theap_meta` which uses a detached tld with
22	  a detached thread id. The initial theap_meta is statically 
23	  allocated and can thus be used to allocate on an as yet
24	  uninitialized thread or process.
25	  We need to take a lock though to allocate safely on the
26	  detached `theap_meta`.
27	----------------------------------------------------------- */
28	
29	void* _mi_meta_zalloc( mi_subproc_t* subproc, size_t size, mi_memid_t* memid ) {
30	  mi_assert_internal(subproc->theap_meta != NULL);
31	  void* p = NULL;
32	  mi_lock(&subproc->theap_meta_lock) {
33	    p = mi_theap_zalloc(subproc->theap_meta, size);
34	    if (memid != NULL) { *memid = (p==NULL ? _mi_memid_none() : _mi_memid_create_malloc(p,size,true) ); }
35	  }
36	  return p;
37	}
38	
39	void* _mi_meta_zalloc_aligned( mi_subproc_t* subproc, size_t size, size_t aligned, mi_memid_t* memid ) {
40	  mi_assert_internal(subproc->theap_meta != NULL);
41	  void* p = NULL;
42	  mi_lock(&subproc->theap_meta_lock) {
43	    p = mi_theap_zalloc_aligned(subproc->theap_meta, size, aligned);
44	    if (memid != NULL) { *memid = (p==NULL ? _mi_memid_none() : _mi_memid_create_malloc(p,size,true) ); }
45	  }
46	  return p;
47	}
48	
49	void* _mi_meta_rezalloc( mi_subproc_t* subproc, void* oldp, size_t newsize, mi_memid_t* memid ) {
50	  mi_assert_internal(subproc->theap_meta != NULL);
51	  // note: since we take a meta lock we cannot use `mi_theap_rezalloc` as that could call `mi_free` which
52	  // can call `mi_stat_free` which would try to take the meta lock again. See issue #1358.
53	  void* p = NULL;  
54	  mi_lock(&subproc->theap_meta_lock) {
55	    p = mi_theap_zalloc(subproc->theap_meta, newsize);
56	  }
57	  if (p!=NULL) {
58	    if (oldp!=NULL) {
59	      const size_t oldsize  = mi_usable_size(oldp);
60	      const size_t copysize = (newsize < oldsize ? newsize : oldsize);
61	      _mi_memcpy(p,oldp,copysize);
62	      if (memid!=NULL) { _mi_meta_free(subproc,oldp,*memid); } 
63	                  else { mi_free(oldp); }
64	    }
65	    if (memid!=NULL) { *memid = _mi_memid_create_malloc(p,newsize,true); }
66	  }
67	  else {
68	    if (memid!=NULL) { *memid = _mi_memid_none(); }  
69	  }
70	  return p;
71	}
72	
73	void _mi_meta_free(mi_subproc_t* subproc, void* p, mi_memid_t memid) {
74	  if (p==NULL || mi_memid_needs_no_free(memid)) return;
75	  if (memid.memkind == MI_MEM_MALLOC) {
76	    mi_free(p);
77	  }
78	  else {
79	    mi_assert_internal(subproc!=NULL);  
80	    _mi_arenas_free(subproc, p, _mi_memid_size(memid), memid);
81	  }
82	}
83	
84	bool _mi_meta_is_meta_page(const mi_subproc_t* subproc, const mi_page_t* page) {
85	  if (page==NULL) return false;
86	  mi_theap_t* theap = page->theap;
87	  return (theap != NULL && theap == subproc->theap_meta);
88	}
89	
90	
91	/* -----------------------------------------------------------
92	  Sub process helpers
93	----------------------------------------------------------- */
94	
95	mi_subproc_t* _mi_subproc_main(void) {
96	  return &mi_process_subproc_main;
97	}
98	
99	bool _mi_subproc_is_main(mi_subproc_t* subproc) {
100	  return (subproc == &mi_process_subproc_main);
101	}
102	
103	mi_subproc_t* _mi_subproc(void) {
104	  mi_theap_t* theap = _mi_theap_default();
105	  if (theap == NULL || theap->tld == NULL) {  // see issue #1289
106	    return _mi_subproc_main();
107	  }
108	  else {
109	    return theap->tld->subproc;
110	  }
111	}
112	
113	mi_heap_t* mi_heap_main(void) {
114	  return _mi_subproc_heap_main(_mi_subproc()); // don't use mi_theap_main_init_get() so this call works during process_init
115	}
116	
117	
118	mi_subproc_t* _mi_subproc_from_id(mi_subproc_id_t subproc_id) {
119	  return (mi_subproc_t*)(subproc_id._mi_subproc_id);
120	}
121	
122	mi_subproc_id_t _mi_subproc_to_id(mi_subproc_t* subproc) {
123	  mi_subproc_id_t id = { subproc };
124	  return id;
125	}
126	
127	mi_subproc_id_t mi_subproc_main(void) {
128	  return _mi_subproc_to_id(_mi_subproc_main());
129	}
130	
131	mi_subproc_id_t mi_subproc_current(void) {
132	  return _mi_subproc_to_id(_mi_subproc());
133	}
134	
135	
136	/* -----------------------------------------------------------
137	  Sub process creation
138	----------------------------------------------------------- */
139	
140	
141	static mi_subproc_t* mi_subproc_init(mi_subproc_t* subproc, mi_subproc_t* parent) {
142	  static _Atomic(size_t) subproc_total_count;
143	  subproc->parent = parent;
144	  subproc->subproc_seq = mi_atomic_increment_relaxed(&subproc_total_count);
145	  mi_stats_header_init(&subproc->stats);
146	  mi_lock_init(&subproc->arena_reserve_lock);
147	  mi_lock_init(&subproc->heaps_lock);
148	  mi_lock_init(&subproc->theap_meta_lock);
149	  mi_lock(&mi_subprocs_lock) {
150	    // push on subproc list
151	    subproc->next = mi_subprocs;
152	    if (mi_subprocs!=NULL) { mi_subprocs->prev = subproc; }
153	    mi_subprocs = subproc;
154	  }
155	  return subproc;
156	}
157	
158	mi_subproc_id_t mi_subproc_new(void) {
159	  mi_thread_init();
160	  mi_subproc_t* const parent = _mi_subproc();
161	  mi_memid_t memid;
162	  mi_subproc_t* const subproc = (mi_subproc_t*)_mi_meta_zalloc(parent, sizeof(mi_subproc_t), &memid);
163	  if (subproc == NULL) { return _mi_subproc_to_id(NULL); }
164	  subproc->memid  = memid;  
165	  
166	  mi_memid_t theap_memid;
167	  mi_theap_t* const theap_meta = (mi_theap_t*)_mi_meta_zalloc(parent, sizeof(mi_theap_t), &theap_memid);
168	  if (theap_meta==NULL) { 
169	    _mi_meta_free(parent, subproc, memid); 
170	    return _mi_subproc_to_id(NULL); 
171	  }
172	  theap_meta->memid = memid;
173	  
174	  // init subproc
175	  mi_subproc_init(subproc,parent);
176	  
177	  // init main heap
178	  mi_heap_t* heap_main = _mi_heap_new_for_subproc(subproc,0,true);
179	  if (heap_main==NULL) {
180	    _mi_meta_free(parent, theap_meta, theap_meta->memid);
181	    mi_subproc_destroy(_mi_subproc_to_id(subproc));
182	    return _mi_subproc_to_id(NULL);
183	  }
184	  mi_assert_internal(subproc->heap_main == heap_main);
185	
186	  // init meta theap
187	  mi_assert_internal(parent->theap_meta!=NULL);
188	  mi_assert_internal(parent->theap_meta->tld!=NULL);
189	  mi_assert_internal(parent->theap_meta->tld->thread_id == MI_THREADID_DETACHED);
190	  _mi_theap_init(theap_meta,heap_main,parent->theap_meta->tld /* detached tld */);
191	  subproc->theap_meta = theap_meta;
192	
193	  return _mi_subproc_to_id(subproc);
194	}
195	
196	
197	/* -----------------------------------------------------------
198	  Sub process destruction
199	----------------------------------------------------------- */
200	
201	// destroy all subproc resources including arena's, heap's etc.
202	static void mi_subproc_unsafe_destroy(mi_subproc_t* subproc, bool acquire_subprocs_lock)
203	{
204	  if (subproc==NULL) return;
205	
206	  // remove from the subproc list
207	  mi_lock_maybe(&mi_subprocs_lock, acquire_subprocs_lock) {
208	    if (subproc->next!=NULL) { subproc->next->prev = subproc->prev;  }
209	    if (subproc->prev!=NULL) { subproc->prev->next = subproc->next;  }
210	                        else { mi_assert_internal(mi_subprocs==subproc);  mi_subprocs = subproc->next; }
211	  }
212	
213	  // destroy all subproc heaps
214	  mi_lock(&subproc->heaps_lock) {
215	    mi_heap_t* heap = subproc->heaps;
216	    while (heap != NULL) {
217	      mi_heap_t* next = heap->next;
218	      if (heap!=subproc->heap_main) { _mi_heap_force_destroy(heap, false /* don't re-acquire the heaps_lock */); }
219	      heap = next;
220	    }
221	    mi_assert_internal(subproc->heap_main==NULL || subproc->heaps == subproc->heap_main);
222	    if (subproc->heap_main!=NULL) {
223	      _mi_thread_locals_thread_done(); // release thread locals that may have been allocated (safe as the main heap uses the fast key)
224	      if (_mi_subproc_is_main(subproc)) {
225	        _mi_thread_locals_done();      
226	      }
227	      _mi_heap_force_destroy(subproc->heap_main, false /* don't re-acquire the heaps_lock */);  // no warning if destroying the main heap
228	    }
229	  }
230	
231	  subproc->theap_meta = NULL; // theap meta stats are merged during heap_destroy of the main heap
232	
233	  if (!_mi_subproc_is_main(subproc)) {
234	    // merge stats back into the main subproc  
235	    _mi_stats_merge_into(&mi_process_subproc_main.stats, &subproc->stats);
236	  }
237	
238	  // remove associated arenas
239	  _mi_arenas_unsafe_destroy_all(subproc);
240	
241	  // show stats of the main process (at process end) before releasing the heaps lock
242	  if (_mi_subproc_is_main(subproc)) {
243	    if (mi_option_is_enabled(mi_option_show_stats) || mi_option_is_enabled(mi_option_verbose)) {
244	      mi_subproc_stats_print_out(mi_subproc_main(), NULL, NULL);
245	    }
246	  }
247	
248	  // todo: should we refcount subprocesses?
249	  mi_lock_done(&subproc->arena_reserve_lock);
250	  mi_lock_done(&subproc->heaps_lock);
251	  mi_lock_done(&subproc->theap_meta_lock);  
252	  _mi_meta_free( subproc->parent, subproc, subproc->memid);  
253	  if (_mi_subproc_is_main(subproc)) {
254	    // for the main subproc, also release the global page map
255	    _mi_page_map_unsafe_destroy();
256	  }
257	}
258	
259	void mi_subproc_destroy(mi_subproc_id_t subproc_id) {
260	  mi_subproc_t* subproc = _mi_subproc_from_id(subproc_id);
261	  if (subproc==NULL || subproc==&mi_process_subproc_main) return;
262	  mi_subproc_unsafe_destroy(subproc, true /* take lock */);
263	}
264	
265	void _mi_subprocs_unsafe_destroy_all(void) {
266	  mi_lock(&mi_subprocs_lock) {
267	    mi_subproc_t* subproc = mi_subprocs;
268	    while (subproc!=NULL) {
269	      mi_subproc_t* next = subproc->next;
270	      if (subproc!=&mi_process_subproc_main) {
271	        mi_subproc_unsafe_destroy(subproc, false /* take mi_subprocs lock */);
272	      }
273	      subproc = next;
274	    }
275	  }
276	  mi_subproc_unsafe_destroy(&mi_process_subproc_main, true /* take mi_subprocs lock */);
277	}
278	
279	
280	/* -----------------------------------------------------------
281	  Sub process various
282	----------------------------------------------------------- */
283	
284	void mi_subproc_add_current_thread(mi_subproc_id_t subproc_id) {
285	  mi_subproc_t* subproc = _mi_subproc_from_id(subproc_id);
286	  mi_assert_internal(subproc!=NULL);
287	  if (subproc==NULL) return;
288	  mi_assert_internal(subproc->heap_main!=NULL);
289	  if (subproc->heap_main==NULL) return;
290	  mi_theap_t* theap = _mi_theap_default();
291	  if (mi_theap_is_initialized(theap)) {
292	    if (theap->tld!=NULL && theap->tld->subproc != subproc) {
293	      _mi_warning_message("unable to add thread to the subprocess as it was already in another subprocess (at %p)\n", theap->tld->subproc);
294	    }
295	    return;
296	  }
297	
298	  // initialize this thread tld & theap
299	  _mi_thread_init_with_heap(subproc->heap_main);
300	}
301	
302	
303	bool mi_subproc_visit_heaps(mi_subproc_id_t subproc_id, mi_heap_visit_fun* visitor, void* arg) {
304	  mi_subproc_t* subproc = _mi_subproc_from_id(subproc_id);
305	  if (subproc==NULL) return false;
306	  bool ok = true;
307	  mi_lock(&subproc->heaps_lock) {
308	    for (mi_heap_t* heap = subproc->heaps; heap!=NULL && ok; heap = heap->next) {
309	      ok = (*visitor)(heap, arg);
310	    }
311	  }
312	  return ok;
313	}
314	
315	
316	mi_subproc_t* _mi_subproc_main_init(void) {
317	  mi_lock_init(&mi_subprocs_lock);
318	  mi_memid_t memid = _mi_memid_create_static(&mi_process_subproc_main,sizeof(mi_subproc_t));
319	  mi_process_subproc_main.memid = memid;
320	  mi_subproc_init(&mi_process_subproc_main,NULL);
321	  return &mi_process_subproc_main;
322	}
323	
324	void _mi_subproc_main_done(void) {
325	  mi_lock_done(&mi_subprocs_lock);
326	}
327	
